/**
 * Element ids generated by the renderer, exported so hosts (HTML exporter, app navigation)
 * can build matching `#fragment` URLs.
 */

/** Prefix of heading ids (avoids clashes with document properties such as `title`). */
export const HEADING_ID_PREFIX = 'h-';

/**
 * Slug of a heading text: NFC, lower-cased, Markdown punctuation removed, whitespace → `-`.
 * Unicode letters (incl. Polish diacritics) are kept: "Zażółć gęślą" → "zażółć-gęślą".
 */
export function slugify(text: string): string {
  const slug = text
    .normalize('NFC')
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\p{M}\s_-]+/gu, '')
    .trim()
    .replace(/[\s_-]*\s[\s_-]*/gu, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^-+|-+$/g, '');
  return slug || 'section';
}

/** Element id of a heading (`h-` + slug), as rendered for `## Text`. Duplicates get `-2`, `-3`... */
export function headingAnchor(text: string): string {
  return HEADING_ID_PREFIX + slugify(text);
}

/** Element id of a block with block id `id` (`^abc123`, like Obsidian Publish). */
export function blockAnchor(id: string): string {
  return `^${id}`;
}

/** Element id of footnote number `n` (with the render's id prefix). */
export function footnoteId(prefix: string, n: number): string {
  return `${prefix}fn-${n}`;
}

/** Element id of the `k`-th reference (1-based) to footnote `n`. */
export function footnoteRefId(prefix: string, n: number, k = 1): string {
  return k <= 1 ? `${prefix}fnref-${n}` : `${prefix}fnref-${n}-${k}`;
}
